-- =====================================================================
-- Projeto de exemplo "ReqTrace Monitor" (conta ryan@gmail.com, nome Ryan)
-- Gerado em 2026-10-28 a partir do banco de desenvolvimento.
--
-- Recria o projeto exatamente como esta: mesmos ids e codigos (RF1..RF22, RNF1..RNF11, RN1..RN7, T1..T11),
-- itens excluidos (para a restauracao de versao continuar funcionando), relacoes, testes e cobertura,
-- as versoes v1 ("Documento de requisitos v1.2") e v2 ("Documento de requisitos v1.3"), as posicoes do
-- grafo e os contadores de codigo (o proximo requisito funcional sera o RF25).
--
-- Contagens: users=1, projects=1, project_members=1, code_sequences=4, elements=42, relationship_types=0, relationships=54, tests=11, test_coverage=14, project_versions=2, graph_positions=34.
--
-- COMO USAR, no outro computador:
--   1. Suba o banco (docker compose up -d, na pasta backend).
--   2. Execute o backend uma vez (mvn spring-boot:run) para o Flyway criar as tabelas (migracoes V1 a V4).
--   3. Rode este script no banco:
--        docker exec -i vvmonitor-postgres psql -U vvmonitor -d vvmonitor < docs/seed-reqtrace-monitor.sql
--   4. Entre no sistema com ryan@gmail.com e a senha ryan12345.
--
-- Se a conta ryan@gmail.com ja existir no destino, ela e reaproveitada (a senha dela nao e alterada).
-- Se o projeto ja existir (mesmo id), o script para sem alterar nada. Tudo roda numa transacao unica.
-- Os demais membros do projeto original (editores) nao sao copiados; posicoes arrastadas por eles ficam
-- em nome do Ryan.
-- =====================================================================

BEGIN;

-- insere as linhas de uma tabela a partir de JSON, trocando os marcadores pelos ids do banco de destino
CREATE FUNCTION pg_temp.vv_load(tbl text, data text) RETURNS void AS $fn$
DECLARE
  ryan uuid;
  t record;
BEGIN
  SELECT id INTO ryan FROM users WHERE email = 'ryan@gmail.com';
  IF tbl = 'users' THEN
    IF ryan IS NOT NULL THEN
      RETURN; -- conta ja existe: reaproveitada, com a senha que ja tem
    END IF;
    ryan := '782335de-dd3c-4f5b-af2f-9c41ea1e35a2'; -- conta nova: mesmo id do banco de origem
  END IF;
  data := replace(data, '__RYAN__', ryan::text);
  FOR t IN SELECT id, name FROM relationship_types WHERE project_id IS NULL LOOP
    data := replace(data, '__TYPE_' || t.name || '__', t.id::text);
  END LOOP;
  IF position('__TYPE_' IN data) > 0 THEN
    RAISE EXCEPTION 'Tipo de relacionamento pre-definido nao encontrado no banco de destino (rode o backend antes).';
  END IF;
  EXECUTE format('INSERT INTO %I SELECT * FROM json_populate_recordset(NULL::%I, $1::json)', tbl, tbl) USING data;
END;
$fn$ LANGUAGE plpgsql;

DO $carga$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM flyway_schema_history WHERE version = '4' AND success) THEN
    RAISE EXCEPTION 'O banco ainda nao tem as tabelas atualizadas (migracao V4). Execute o backend uma vez antes deste script.';
  END IF;
  IF EXISTS (SELECT 1 FROM projects WHERE id = 'a7efb2e4-454e-4fa0-a054-84ab9f9171ec') THEN
    RAISE EXCEPTION 'O projeto ReqTrace Monitor (a7efb2e4-454e-4fa0-a054-84ab9f9171ec) ja existe neste banco. Nada foi alterado.';
  END IF;

  PERFORM pg_temp.vv_load('users', $dados$[{"id":"__RYAN__","name":"Ryan","email":"ryan@gmail.com","password_hash":"$2a$10$j6MQyKIY0XKEt5uXgJR17eACnx48hLr6sOcYy9qRrNgkIdjb30ByO","created_at":"2026-10-05T23:31:12.221548+00:00","updated_at":"2026-10-05T23:31:12.221548+00:00","deleted_at":null}]$dados$);
  PERFORM pg_temp.vv_load('projects', $dados$[{"id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","name":"ReqTrace Monitor","description":"Ferramenta de apoio à validação e à gestão da rastreabilidade de requisitos ao longo do desenvolvimento de um sistema.","owner_id":"__RYAN__","created_at":"2026-10-21T03:38:31.153855+00:00","updated_at":"2026-10-22T02:26:39.480074+00:00","deleted_at":null}]$dados$);
  PERFORM pg_temp.vv_load('project_members', $dados$[{"id":"10f5a52a-509b-4177-9572-7dad291d64b9","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","user_id":"__RYAN__","role":"OWNER","added_at":"2026-10-21T03:38:31.167562+00:00","deleted_at":null}]$dados$);
  PERFORM pg_temp.vv_load('code_sequences', $dados$[{"project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","next_value":25}, {"project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"NON_FUNCTIONAL","next_value":12}, {"project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"BUSINESS_RULE","next_value":8}, {"project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"TEST","next_value":12}]$dados$);
  PERFORM pg_temp.vv_load('elements', $dados$[{"id":"d97549a9-51ca-4de9-8ad6-e7895aad278d","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF1","description":"Permitir que o usuário realize cadastro informando nome, e-mail e senha.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.285787+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"731680ab-4c2b-44a7-94e7-ccfdff079a80","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF2","description":"Usuário deve ser capaz de logar no sistema usando e-mail e senha.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.344888+00:00","updated_at":"2026-10-22T02:23:55.98158+00:00","deleted_at":null}, {"id":"acbe6bfe-415c-46bb-8c41-e5b27374f7c3","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF3","description":"Permitir que o usuário visualize projetos existentes.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.375133+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"a3648aba-3ad2-419b-b616-ea48028eb18f","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF4","description":"Usuário deve ser capaz de cadastrar novo projeto, informando nome e, opcionalmente, descrição.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.400204+00:00","updated_at":"2026-10-22T02:23:56.102716+00:00","deleted_at":null}, {"id":"bc958988-d8cb-42d4-be9d-e37b1f149152","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF5","description":"Usuário deve ser capaz de cadastrar requisitos de um projeto, atribuindo descrição e prioridade (obrigatório, desejável, opcional), com identificador gerado dinamicamente.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.421735+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"05ce5c04-9ad8-4338-89a7-ac0914b04a83","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF6","description":"Usuário deve ser capaz de cadastrar regras de negócio, atribuindo descrição, com identificador gerado dinamicamente.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.461585+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"b43b2055-5348-4a03-9efc-2ba3ef9f0e66","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF7","description":"Usuário deve ser capaz de estabelecer relações entre requisitos funcionais, não funcionais e regras de negócio.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.482659+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"1d1739b5-995d-4673-a3f0-12d1418de029","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF8","description":"Usuário deve ser capaz de escolher o tipo de relacionamento entre elementos, entre os pré-definidos ou criando um novo.","priority":"DESIRABLE","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.50927+00:00","updated_at":"2026-10-22T02:23:56.171494+00:00","deleted_at":null}, {"id":"8db6deda-0942-4283-8a08-e8eef441bfc7","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF9","description":"Permitir cadastrar testes relacionados aos requisitos funcionais e não funcionais, com descrição do teste. Todo teste deve cobrir ao menos um requisito; regras de negócio não são cobertas por testes.","priority":"OPTIONAL","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.554528+00:00","updated_at":"2026-10-22T02:23:56.235808+00:00","deleted_at":null}, {"id":"c91f1a01-9b14-45b5-a47d-2e0b0d2cbb30","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF10","description":"Usuário deve ser capaz de submeter o modelo do projeto (requisitos, regras de negócio, relações e testes), gerando uma versão imutável, identificada por número sequencial e nome opcional.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.60601+00:00","updated_at":"2026-10-22T02:23:56.309324+00:00","deleted_at":null}, {"id":"e0adbf52-2a0a-4432-82f5-32733f23ba0d","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF11","description":"Sistema deve apresentar representação visual do modelo atual (requisitos, regras de negócio, testes e relacionamentos), destacando as alterações ainda não submetidas.","priority":"DESIRABLE","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.655458+00:00","updated_at":"2026-10-22T02:23:56.358263+00:00","deleted_at":null}, {"id":"87d55298-4960-454d-a804-edfa5af29d51","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF12","description":"Usuário deve poder escolher o modelo de visualização (lista, matriz de rastreabilidade ou grafo), alternando entre eles.","priority":"OPTIONAL","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.704021+00:00","updated_at":"2026-10-22T02:23:56.419384+00:00","deleted_at":null}, {"id":"733907dd-c0f7-49e5-a075-325fccfbf610","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF13","description":"Sistema deve indicar quais requisitos têm ou não testes associados (visual e mensagens de texto), incluindo cobertura.","priority":"OPTIONAL","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.755519+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"d1f61483-7d65-4d40-9714-86353df340d0","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF14","description":"Usuário deve ser capaz de editar conteúdos dos requisitos, descrições e suas relações.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.794092+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"b023afdc-5e6d-4f9b-a7ba-8ba5fdc11197","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF15","description":"Usuário deve ser capaz de remover requisitos e suas associações, podendo excluir junto os testes que ficariam sem requisito.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.83468+00:00","updated_at":"2026-10-22T02:23:56.481523+00:00","deleted_at":null}, {"id":"aee65e49-ee6f-4da6-ac08-090bcb75a391","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF16","description":"Sistema deve indicar os elementos e testes que podem ser afetados ao editar ou excluir um requisito ou regra de negócio, incluindo os dependentes indiretos, e alertar o usuário quando a exclusão implica mudanças relevantes (níveis de impacto baixo, médio e alto, ex. requisito órfão, muitos vínculos).","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.888002+00:00","updated_at":"2026-10-22T02:23:56.539036+00:00","deleted_at":null}, {"id":"bd632d58-6297-47dd-97e0-bd5e239be18c","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF17","description":"Usuário deve ser capaz de salvar o estado atual do projeto, criando versões acessadas posteriormente.","priority":"DESIRABLE","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.94186+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":"2026-10-22T02:23:56.817657+00:00"}, {"id":"69667236-e062-494c-b2b7-0f29c77c908f","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF18","description":"Usuário deve ser capaz de visualizar as diferentes versões do projeto e compará-las entre si ou com o modelo atual.","priority":"OPTIONAL","created_by":"__RYAN__","created_at":"2026-10-21T03:38:31.984012+00:00","updated_at":"2026-10-22T02:23:56.587041+00:00","deleted_at":null}, {"id":"7be3c212-60d3-4bf8-b393-9aa0543e7efc","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF19","description":"Sistema deve integrar-se a plataformas de gestão de projeto (Trello, Jira, ClickUp).","priority":"OPTIONAL","created_by":"__RYAN__","created_at":"2026-10-21T03:38:32.015065+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":"2026-10-22T02:23:56.865385+00:00"}, {"id":"6c067381-6f25-412f-b7fe-1192ba5e2169","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"FUNCTIONAL","code":"RF20","description":"Usuário deve ser capaz de compartilhar o acesso ao projeto com outros usuários cadastrados, via adição de e-mail. Somente o proprietário adiciona pessoas, que entram com permissão de edição; o proprietário pode remover o acesso de editores, e cada editor pode sair do projeto.","priority":"DESIRABLE","created_by":"__RYAN__","created_at":"2026-10-21T03:38:32.034285+00:00","updated_at":"2026-10-22T02:23:56.625794+00:00","deleted_at":null}, {"id":"560b7984-f4f6-4c34-942e-0aedd3892c50","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"NON_FUNCTIONAL","code":"RNF1","description":"Impedir que usuários não autenticados acessem projetos e informações armazenadas.","priority":"MANDATORY","created_by":"__RYAN__","created_at":"2026-10-21T03:38:32.074053+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"74669d9d-45f2-46ff-802d-d4252c8c0f99","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"NON_FUNCTIONAL","code":"RNF2","description":"Salvar diferentes versões do projeto de maneira imutável, para fins de auditoria.","priority":"DESIRABLE","created_by":"__RYAN__","created_at":"2026-10-21T03:38:32.107944+00:00","updated_at":"2026-10-21T23:09:57.984872+00:00","deleted_at":null}, {"id":"c09bafab-7ef5-4628-8ee3-9d5e6abe146b","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","kind":"NON_FUNCTIONAL","code":"RNF3","description":"Armazenar senhas utilizando o algoritmo de hash Bcrypt.","priority":"MAND