48028eb18f"}, {"id": "727b3032-d23c-49dd-8682-26a060df3070", "typeId": "__TYPE_Dependência__", "sourceId": "05ce5c04-9ad8-4338-89a7-ac0914b04a83", "targetId": "a3648aba-3ad2-419b-b616-ea48028eb18f"}, {"id": "7cf1a590-3dd1-4180-8b85-9a54e4d2fefb", "typeId": "__TYPE_Dependência__", "sourceId": "d1f61483-7d65-4d40-9714-86353df340d0", "targetId": "b43b2055-5348-4a03-9efc-2ba3ef9f0e66"}, {"id": "7d8d2194-cf0e-4e8e-aa15-1a75a70f5cc0", "typeId": "__TYPE_Dependência__", "sourceId": "05ce5c04-9ad8-4338-89a7-ac0914b04a83", "targetId": "b9fc313e-0181-4353-b556-dd2b1859be7d"}, {"id": "7ffd5af5-87ad-494c-bd74-ad7a9df0da2e", "typeId": "__TYPE_Dependência__", "sourceId": "b43b2055-5348-4a03-9efc-2ba3ef9f0e66", "targetId": "092641a1-ae67-4144-9054-14af86a94a34"}]},"created_by":"__RYAN__","created_at":"2026-10-21T03:38:34.94622+00:00"}, {"id":"a8082d45-c541-48c7-b2e3-42e9f40331c5","project_id":"a7efb2e4-454e-4fa0-a054-84ab9f9171ec","version_number":2,"label":"Documento de requisitos v1.3","snapshot":{"tests": [{"id": "6032db76-653d-4845-8a96-d2525c828c5a", "code": "T1", "elementIds": ["c09bafab-7ef5-4628-8ee3-9d5e6abe146b", "d97549a9-51ca-4de9-8ad6-e7895aad278d"], "description": "Cadastrar conta com nome, e-mail e senha válidos e verificar que a senha é armazenada com hash."}, {"id": "cb4d7188-8c8e-434f-8426-e436d9c1b865", "code": "T2", "elementIds": ["d97549a9-51ca-4de9-8ad6-e7895aad278d"], "description": "Tentar cadastrar com um e-mail já cadastrado e verificar a mensagem de erro."}, {"id": "297585af-7c83-4f68-a1d4-5815f197a5ba", "code": "T3", "elementIds": ["731680ab-4c2b-44a7-94e7-ccfdff079a80"], "description": "Entrar com e-mail e senha corretos e ver a tela inicial dos projetos."}, {"id": "3a304775-98e9-4665-b936-d21a4cb7b255", "code": "T4", "elementIds": ["731680ab-4c2b-44a7-94e7-ccfdff079a80"], "description": "Entrar com a senha errada e verificar que o ator permanece no login."}, {"id": "7e9c5f30-6baa-45a3-990b-f86d6d370557", "code": "T5", "elementIds": ["560b7984-f4f6-4c34-942e-0aedd3892c50"], "description": "Acessar a página de um projeto sem estar autenticado e ser redirecionado ao login."}, {"id": "0ab39da6-6611-4f45-97ae-82eb71e7f503", "code": "T6", "elementIds": ["a3648aba-3ad2-419b-b616-ea48028eb18f"], "description": "Criar projeto com nome e descrição e ser direcionado a ele."}, {"id": "ffa9d507-8e4f-4460-835e-4f62ccb84310", "code": "T7", "elementIds": ["bc958988-d8cb-42d4-be9d-e37b1f149152"], "description": "Cadastrar requisito com prioridade e verificar o identificador gerado."}, {"id": "5c457f60-4742-4ae6-ac32-fb24f3e5fbdf", "code": "T8", "elementIds": ["05ce5c04-9ad8-4338-89a7-ac0914b04a83"], "description": "Cadastrar regra de negócio e verificar o identificador gerado."}, {"id": "db58d433-9fc0-4c0b-a9da-9e0e718049da", "code": "T9", "elementIds": ["b43b2055-5348-4a03-9efc-2ba3ef9f0e66", "1d1739b5-995d-4673-a3f0-12d1418de029"], "description": "Relacionar dois requisitos com tipo Dependência e verificar o vínculo nas duas pontas."}, {"id": "30286281-5ec2-487b-af61-7eccf446026d", "code": "T10", "elementIds": ["d1f61483-7d65-4d40-9714-86353df340d0"], "description": "Editar a descrição de um requisito e conferir a alteração na lista."}, {"id": "d08fbd30-3f8e-4693-adae-9c79525bfeed", "code": "T11", "elementIds": ["aee65e49-ee6f-4da6-ac08-090bcb75a391", "b023afdc-5e6d-4f9b-a7ba-8ba5fdc11197"], "description": "Excluir um requisito com vínculos e verificar o nível de impacto exibido."}], "types": [{"id": "__TYPE_Dependência__", "name": "Dependência", "custom": false, "symmetric": false}, {"id": "__TYPE_Refinamento__", "name": "Refinamento", "custom": false, "symmetric": false}, {"id": "__TYPE_Conflito__", "name": "Conflito", "custom": false, "symmetric": true}, {"id": "__TYPE_Similaridade__", "name": "Similaridade", "custom": false, "symmetric": true}], "format": 2, "changes": {"added": 15, "removed": 7, "modified": 13}, "elements": [{"id": "d97549a9-51ca-4de9-8ad6-e7895aad278d", "code": "RF1", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Permitir que o usuário realize cadastro informando nome, e-mail e senha."}, {"id": "731680ab-4c2b-44a7-94e7-ccfdff079a80", "code": "RF2", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de logar no sistema usando e-mail e senha."}, {"id": "acbe6bfe-415c-46bb-8c41-e5b27374f7c3", "code": "RF3", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Permitir que o usuário visualize projetos existentes."}, {"id": "a3648aba-3ad2-419b-b616-ea48028eb18f", "code": "RF4", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de cadastrar novo projeto, informando nome e, opcionalmente, descrição."}, {"id": "bc958988-d8cb-42d4-be9d-e37b1f149152", "code": "RF5", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de cadastrar requisitos de um projeto, atribuindo descrição e prioridade (obrigatório, desejável, opcional), com identificador gerado dinamicamente."}, {"id": "05ce5c04-9ad8-4338-89a7-ac0914b04a83", "code": "RF6", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de cadastrar regras de negócio, atribuindo descrição, com identificador gerado dinamicamente."}, {"id": "b43b2055-5348-4a03-9efc-2ba3ef9f0e66", "code": "RF7", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de estabelecer relações entre requisitos funcionais, não funcionais e regras de negócio."}, {"id": "1d1739b5-995d-4673-a3f0-12d1418de029", "code": "RF8", "kind": "FUNCTIONAL", "priority": "DESIRABLE", "description": "Usuário deve ser capaz de escolher o tipo de relacionamento entre elementos, entre os pré-definidos ou criando um novo."}, {"id": "8db6deda-0942-4283-8a08-e8eef441bfc7", "code": "RF9", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Permitir cadastrar testes relacionados aos requisitos funcionais e não funcionais, com descrição do teste. Todo teste deve cobrir ao menos um requisito; regras de negócio não são cobertas por testes."}, {"id": "c91f1a01-9b14-45b5-a47d-2e0b0d2cbb30", "code": "RF10", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de submeter o modelo do projeto (requisitos, regras de negócio, relações e testes), gerando uma versão imutável, identificada por número sequencial e nome opcional."}, {"id": "e0adbf52-2a0a-4432-82f5-32733f23ba0d", "code": "RF11", "kind": "FUNCTIONAL", "priority": "DESIRABLE", "description": "Sistema deve apresentar representação visual do modelo atual (requisitos, regras de negócio, testes e relacionamentos), destacando as alterações ainda não submetidas."}, {"id": "87d55298-4960-454d-a804-edfa5af29d51", "code": "RF12", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Usuário deve poder escolher o modelo de visualização (lista, matriz de rastreabilidade ou grafo), alternando entre eles."}, {"id": "733907dd-c0f7-49e5-a075-325fccfbf610", "code": "RF13", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Sistema deve indicar quais requisitos têm ou não testes associados (visual e mensagens de texto), incluindo cobertura."}, {"id": "d1f61483-7d65-4d40-9714-86353df340d0", "code": "RF14", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de editar conteúdos dos requisitos, descrições e suas relações."}, {"id": "b023afdc-5e6d-4f9b-a7ba-8ba5fdc11197", "code": "RF15", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Usuário deve ser capaz de remover requisitos e suas associações, podendo excluir junto os testes que ficariam sem requisito."}, {"id": "aee65e49-ee6f-4da6-ac08-090bcb75a391", "code": "RF16", "kind": "FUNCTIONAL", "priority": "MANDATORY", "description": "Sistema deve indicar os elementos e testes que podem ser afetados ao editar ou excluir um requisito ou regra de negócio, incluindo os dependentes indiretos, e alertar o usuário quando a exclusão implica mudanças relevantes (níveis de impacto baixo, médio e alto, ex. requisito órfão, muitos vínculos)."}, {"id": "69667236-e062-494c-b2b7-0f29c77c908f", "code": "RF18", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Usuário deve ser capaz de visualizar as diferentes versões do projeto e compará-las entre si ou com o modelo atual."}, {"id": "6c067381-6f25-412f-b7fe-1192ba5e2169", "code": "RF20", "kind": "FUNCTIONAL", "priority": "DESIRABLE", "description": "Usuário deve ser capaz de compartilhar o acesso ao projeto com outros usuários cadastrados, via adição de e-mail. Somente o proprietário adiciona pessoas, que entram com permissão de edição; o proprietário pode remover o acesso de editores, e cada editor pode sair do projeto."}, {"id": "56837beb-385b-4fc7-948e-a99b7c2fdeca", "code": "RF21", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Sistema deve salvar automaticamente a posição dos elementos e testes reorganizados pelo usuário na visualização em grafo, mantendo-a para todos os membros do projeto."}, {"id": "9b3afb3e-820d-48b1-8b72-3bb64af27086", "code": "RF22", "kind": "FUNCTIONAL", "priority": "OPTIONAL", "description": "Usuário deve ser capaz de restaurar o projeto para uma versão salva, sem apagar as versões posteriores. As alterações ainda não salvas em versão são perdidas, com aviso prévio."}, {"id": "560b7984-f4f6-4c34-942e-0aedd3892c50", "code": "RNF1", "kind": "NON_FUNCTIONAL", "priority": "MANDATORY", "description": "Impedir que usuários não autenticados acessem projetos e informações armazenadas."}, {"id": "74669d9d-45f2-46ff-802d-d4252c8c0f99", "code": "RNF2", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Salvar diferentes versões do projeto de maneira imutável, para fins de auditoria."}, {"id": "c09bafab-7ef5-4628-8ee3-9d5e6abe146b", "code": "RNF3", "kind": "NON_FUNCTIONAL", "priority": "MANDATORY", "description": "Armazenar senhas utilizando o algoritmo de hash Bcrypt."}, {"id": "14093f87-6a79-4eea-a827-6075e7f17f70", "code": "RNF4", "kind": "NON_FUNCTIONAL", "priority": "MANDATORY", "description": "Garantir proteção de dados sensíveis via controle de acesso, armazenamento seguro de senhas e restrição conforme permissões (proprietário e editor)."}, {"id": "7e53f1cf-7a3c-4c35-b1d0-4f73bedbfc76", "code": "RNF5", "kind": "NON_FUNCTIONAL", "priority": "OPTIONAL", "description": "Documentação deve seguir padrão de versionamento que permita identificar e registrar versões do projeto, numeradas sequencialmente (v1, v2, v3…)."}, {"id": "06e3f70d-6ec5-4d5b-9405-3d7f5486f57a", "code": "RNF6", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Possuir tratamento de exceções, garantindo finalização dos fluxos sem interrupções inesperadas."}, {"id": "7fc16517-e0aa-4b2c-bf12-cfce3a8c23f1", "code": "RNF7", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Suportar 1.000 usuários simultâneos e 100.000 registros, com tempo de resposta adequado."}, {"id": "9e33b487-e464-481f-9021-1bceaf26f59b", "code": "RNF8", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Interface utilizável sem conhecimento prévio, permitindo cadastro e criação de projeto em até 30 minutos."}, {"id": "9cb48db4-837f-471a-bdba-1b2797db78f0", "code": "RNF9", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Qualquer parte do sistema deve ser acessível com no máximo 3 cliques."}, {"id": "7a8133b3-cce1-4f90-9abf-6b2ad20c1e36", "code": "RNF10", "kind": "NON_FUNCTIONAL", "priority": "MANDATORY", "description": "Backend implementado em Java 21, com Spring Boot."}, {"id": "0cd65f17-452a-4590-8310-d5a51e2e68fd", "code": "RNF11", "kind": "NON_FUNCTIONAL", "priority": "DESIRABLE", "description": "Toda comunicação entre cliente e servidor deve usar HTTPS."}, {"id": "27d8d9fa-0e26-4fe7-a48e-559042a69a40", "code": "RN1", "kind": "BUSINESS_RULE", "priority": null, "description": "O e-mail do cadastro deve ser único: e-mail já cadastrado não cria nova conta (UC-01, exceção do passo 4)."}, {"id": "fa02128f-71bf-4f75-90af-da6ed70d27d9", "code": "RN2", "kind": "BUSINESS_RULE", "priority": null, "description": "No cadastro, a senha e a confirmação de senha devem ser iguais (UC-01, passo 2)."}, {"id": "092641a1-ae67-4144-9054-14af86a94a34", "code": "RN3", "kind": "BUSINESS_RULE", "priority": null, "description": "Um relacionamento já existente entre os mesmos elementos não é registrado de novo (UC-06, exceção do passo 6)."}, {"id": "b9fc313e-0181-4353-b556-dd2b1859be7d", "code": "RN4", "kind": "BUSINESS_RULE", "priority": null, "description": "O identificador de requisitos e regras de negócio é gerado dinamicamente pelo sistema (RF5, RF6)."}, {"id": "45184382-609f-4723-b886-d47950798f72", "code": "RN5", "kind": "BUSINESS_RULE", "priority": null, "description": "Todo requisito recebe uma prioridade: obrigatório, desejável ou opcional (RF5)."}, {"id": "bbd5bb20-3420-4745-8962-5b71aff055b4", "code": "RN6", "kind": "BUSINESS_RULE", "priority": null, "description": "Somente o proprietário adiciona pessoas ao projeto, que entram com permissão de edição (RF20)."}, {"id": "20424434-7f19-4855-8f02-4b41c5d51321", "code": "RN7", "kind": "BUSINESS_RULE", "priority": null, "description": "Todo teste cobre ao menos um requisito; regras de negócio não são cobertas por testes (RF9)."}], "relationships": [{"id": "816e3408-0073-42ac-b899-5620eb50a979", "typeId": "__TYPE_Refinamento__", "sourceId": "14093f87-6a79-4eea-a827-6075e7f17f70", "targetId": "560b7984-f4f6-4c34-942e-0aedd3892c50"}, {"id": "88cf4e4a-403d-43ee-9e36-379213c2f002", "typeId": "__TYPE_Dependência__", "sourceId": "bc958988-d8cb-42d4-be9d-e37b1f149152", "targetId": "b9fc313e-0181-4353-b556-dd2b1859be7d"}, {"id": "8ce9b87f-b6d8-44e3-bfef-1446a87ef5fa", "typeId": "__TYPE_Similaridade__", "sourceId": "9cb48db4-837f-471a-bdba-1b2797db78f0", "targetId": "9e33b487-e464-481f-9021-1bceaf26f59b"}, {"id": "8e5ef485-4d50-4496-9177-5b9ef6e1cc32", "typeId": "__TYPE_Refinamento__", "sourceId": "9e33b487-e464-481f-9021-1